/** The HELD touch channels (all optional, default off). */
export interface TouchChannels {
  /** Thrust demand axis (−1..1); >0 forward, <0 backward. */
  thrust?: number;
  /** Yaw demand axis (−1..1); ON-SCREEN direction, >0 turns nose right. */
  yaw?: number;
  /** Pitch demand axis (−1..1); >0 nose up. */
  pitch?: number;
  /** Roll demand axis (−1..1); >0 roll top-right. */
  roll?: number;
  /** VTOL vertical lift (atmosphere). */
  vtol?: boolean;
  /** Space cruise boost. */
  boost?: boolean;
  /** On-foot run. */
  run?: boolean;
  /** On-foot jump. */
  jump?: boolean;
}

/** Virtual key names — must match the keyboard capture (main.tsx's keyOf). */
const K = {
  thrustUp: 'w',
  thrustDown: 's',
  yawRight: 'd',
  yawLeft: 'a',
  pitchUp: 'f',
  pitchDown: 'r',
  rollRight: 'e',
  rollLeft: 'q',
  space: ' ',
  shift: 'Shift',
} as const;

/**
 * Owns the set of active touch channels and projects the HELD ones to
 * virtual key names. Discrete actions are not represented here (see header).
 */
export class TouchInputSource {
  private channels: TouchChannels = {};

  /**
   * Merge the given channels into the current set. Channels NOT present
   * in `channels` are left as-is (partial updates, e.g. a joystick
   * writing only {thrust, yaw} never clobbers the vtol button).
   */
  setChannel(channels: Partial<TouchChannels>): void {
    for (const [key, value] of Object.entries(channels)) {
      if (value === undefined) continue;
      (this.channels as Record<string, unknown>)[key] = value;
    }
  }

  /** Reset every channel off. */
  clear(): void {
    this.channels = {};
  }

  /**
   * Project the ACTIVE HELD channels to virtual key names (union of all
   * active projections; the intentional collisions collapse in the Set).
   */
  virtualKeys(): ReadonlySet<string> {
    const c = this.channels;
    const keys = new Set<string>();
    if ((c.thrust ?? 0) > 0) keys.add(K.thrustUp);
    if ((c.thrust ?? 0) < 0) keys.add(K.thrustDown);
    if ((c.yaw ?? 0) > 0) keys.add(K.yawRight);
    if ((c.yaw ?? 0) < 0) keys.add(K.yawLeft);
    if ((c.pitch ?? 0) > 0) keys.add(K.pitchUp);
    if ((c.pitch ?? 0) < 0) keys.add(K.pitchDown);
    if ((c.roll ?? 0) > 0) keys.add(K.rollRight);
    if ((c.roll ?? 0) < 0) keys.add(K.rollLeft);
    if (c.vtol) keys.add(K.space);
    if (c.boost) keys.add(K.shift);
    if (c.run) keys.add(K.shift);
    if (c.jump) keys.add(K.space);
    return keys;
  }
}

